INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: easy / L1 — Clearly trivial threshold definition
(1, 'Misstatements and Control Deficiencies', 'What is the significance of the "clearly trivial" threshold under AU-C 450?', '["It establishes a level below which misstatements need not be accumulated during the audit", "It sets the maximum amount of any single misstatement before a qualified opinion is required", "It determines whether management must correct all identified errors before the report date", "It defines the boundary between significant deficiencies and material weaknesses"]'::jsonb, 0, 'Under AU-C 450.05, the auditor establishes an amount below which misstatements are clearly trivial and need not be accumulated. This threshold represents amounts that are inconsequential both individually and in the aggregate, distinct from a smaller materiality figure. Choice B is incorrect because the clearly trivial threshold relates to accumulation of misstatements for evaluation, not to opinion modification, which is governed by overall materiality under AU-C 705.', 'easy', 1),

-- Q2: easy / L1 — Tolerable misstatement definition
(1, 'Misstatements and Control Deficiencies', 'Under auditing standards, what does "tolerable misstatement" refer to?', '["The maximum aggregate of uncorrected misstatements before an adverse opinion is issued", "The application of performance materiality to a specific sampling procedure", "The threshold for communicating misstatements to those charged with governance", "The amount below which misstatements are considered clearly trivial"]'::jsonb, 1, 'Under AU-C 530.07, tolerable misstatement is the application of performance materiality to a particular sampling procedure, representing the maximum misstatement in a population that the auditor is willing to accept. It links sampling results to the broader audit materiality framework. Choice A is incorrect because opinion modification is based on overall materiality under AU-C 450 and AU-C 705, not on the tolerable misstatement concept used in sampling.', 'easy', 1),

-- Q3: medium / L2 — Applying misstatement classification in scenario
(1, 'Misstatements and Control Deficiencies', 'During the audit of Pinehurst Electronics, the engagement team identifies a $32,000 inventory overstatement caused by a software error that systematically mispriced 200 items. The team verified all 200 affected items and confirmed the total error. Under AU-C 450, this $32,000 amount should be classified as:', '["A judgmental misstatement, because the pricing involved automated estimates", "A clearly trivial misstatement that need not be accumulated for evaluation", "A factual misstatement, because the error amount is known without uncertainty", "A projected misstatement, because the sample must be extrapolated to the population"]'::jsonb, 2, 'Under AU-C 450.A3, a factual misstatement is one about which there is no doubt—the $32,000 error was identified and measured with certainty from the 200 affected items. Since the specific items and their mispricing are known, no projection or estimation is needed. Choice D is incorrect because projected misstatements arise when sample results are extrapolated to estimate total population error; here the entire affected population of 200 items was identified and verified.', 'medium', 2),

-- Q4: medium / L2 — Summary of uncorrected misstatements schedule content
(1, 'Misstatements and Control Deficiencies', 'Ridgeline Aerospace Corp. is being audited by Drake & Whitmore LLP. The audit team has accumulated eight misstatements during testing: four were corrected by management, and four remain uncorrected. When preparing the summary of uncorrected misstatements under AU-C 450, the auditor should include:', '["Only misstatements exceeding performance materiality in the summary", "All eight misstatements, including those already corrected by management", "Only the single largest uncorrected misstatement as representative of the group", "All uncorrected misstatements accumulated during the audit that are not clearly trivial"]'::jsonb, 3, 'Under AU-C 450.06, the auditor accumulates all identified misstatements during the audit other than those that are clearly trivial. The summary of uncorrected misstatements includes all uncorrected items above the clearly trivial threshold for aggregate evaluation. Choice B is incorrect because AU-C 450.08 requires corrected misstatements to be tracked separately; they are not included in the summary of uncorrected misstatements used for aggregate evaluation.', 'medium', 2),

-- Q5: medium / L3 — Analyzing direction of misstatements and bias
(1, 'Misstatements and Control Deficiencies', 'Crestwood Retail Group has ten uncorrected misstatements identified during the 2025 audit. All ten misstatements increase net income, with a combined effect of $38,000 against overall materiality of $75,000. The auditor should analyze this pattern because:', '["A consistent direction of misstatements may indicate management bias, requiring evaluation of intent under AU-C 240", "Misstatements below 50% of materiality are always considered immaterial regardless of directional pattern", "The auditor must issue an adverse opinion whenever misstatements consistently favor increased net income", "AU-C 450 only requires directional analysis when misstatements exceed performance materiality"]'::jsonb, 0, 'Under AU-C 450.A18, when uncorrected misstatements consistently favor one direction—particularly increasing income—the auditor should consider whether this pattern indicates possible management bias. AU-C 240 requires the auditor to evaluate indications of fraud, including bias in estimates. Choice B is incorrect because AU-C 450 requires qualitative evaluation of all uncorrected misstatements regardless of their size relative to materiality, particularly when a pattern of directional bias is present.', 'medium', 3),

-- Q6: medium / L2 — Communication timeline for control deficiencies
(1, 'Misstatements and Control Deficiencies', 'Mercer & Fields LLP completes the audit of Silverstone Technologies on March 15, 2026. During fieldwork in January, the audit team identified a significant deficiency in the IT access control environment. Under AU-C 265, the written communication of this deficiency should be made:', '["Within 30 calendar days of the deficiency being identified during fieldwork", "No later than 60 days after the report release date", "Before the audit opinion is issued on the financial statements", "Within 90 days of the fiscal year end under audit"]'::jsonb, 1, 'Under AU-C 265.13, the auditor must communicate significant deficiencies and material weaknesses in writing to those charged with governance no later than 60 days following the report release date. This provides reasonable time to prepare the communication after the audit concludes. Choice C is incorrect because AU-C 265 permits the written communication to be issued after the audit report is released, not necessarily before the opinion date.', 'medium', 2),

-- Q7: easy / L1 — Control deficiency definition
(1, 'Misstatements and Control Deficiencies', 'What is a control deficiency as defined under AU-C 265?', '["Any violation of regulatory compliance requirements in internal control design", "A weakness that has already resulted in a material misstatement of the financial statements", "A design or operation shortcoming such that a control may not prevent or detect misstatements on a timely basis", "A failure by management to implement all five COSO framework components"]'::jsonb, 2, 'Under AU-C 265.07, a control deficiency exists when the design or operation of a control does not allow management or employees to prevent, or detect and correct, misstatements on a timely basis. This is the broadest category of internal control weakness. Choice B is incorrect because a control deficiency does not require an actual misstatement to have occurred—the mere possibility of failing to prevent or detect misstatements on a timely basis is sufficient.', 'easy', 1),

-- Q8: hard / L4 — Evaluating opinion modification for pervasive uncorrected misstatements
(1, 'Misstatements and Control Deficiencies', 'Pacific Rim Holdings has $180,000 in aggregate uncorrected misstatements against overall materiality of $150,000 and total assets of $12 million. The misstatements span revenue recognition, inventory valuation, and accounts payable—three of the entity''s five major transaction classes. Management declines to make corrections, asserting the amounts are within a reasonable range. The auditor should:', '["Issue an adverse opinion because the misstatements are both material and pervasive to the financial statements", "Issue a qualified opinion because the misstatements exceed materiality but affect only three transaction classes", "Issue an unmodified opinion with an emphasis-of-matter paragraph disclosing the uncorrected misstatements", "Withdraw from the engagement because management''s refusal to correct demonstrates a lack of integrity"]'::jsonb, 0, 'Under AU-C 705.08, when uncorrected misstatements are both material and pervasive, an adverse opinion is required. Misstatements affecting three of five major transaction classes—revenue, inventory, and payables—are pervasive because they are not confined to a single element and affect the financial statements taken as a whole. Choice B is incorrect because a qualified opinion under AU-C 705.07 applies only when misstatements are material but not pervasive; the breadth across multiple transaction classes here makes the effect pervasive.', 'hard', 4),

-- Q9: medium / L3 — Analyzing operating vs. design deficiency
(1, 'Misstatements and Control Deficiencies', 'Thornfield Manufacturing''s accounts payable department has a documented policy requiring supervisor approval for all payments exceeding $5,000. The control is embedded in the accounting software with a system-enforced approval prompt. However, the supervisor has been routinely overriding the prompt and approving payment batches without reviewing individual invoices. This deficiency is best classified as:', '["A design deficiency, because the approval threshold is set too high for the entity''s transaction volume", "A compensating control failure, because no secondary control exists to monitor supervisor overrides", "A design deficiency, because the system allows batch approvals without individual review capability", "An operating deficiency, because the properly designed control is not being performed as intended"]'::jsonb, 3, 'Under AU-C 265.A1, an operating deficiency exists when a properly designed control does not operate effectively or the person performing the control lacks competence or authority. Here, the control is well-designed with a system-enforced approval prompt, but the supervisor is not performing it as intended by routinely overriding it. Choice C is incorrect because the system design appropriately requires approval—the failure lies in how the control is being executed in practice, not in its structural design.', 'medium', 3),

-- Q10: hard / L4 — Recommending action for repeated material weakness
(1, 'Misstatements and Control Deficiencies', 'During the 2025 audit of Bridgeport Community Health System, Hayes & Carroll LLP identifies the same material weakness in revenue cycle controls for the third consecutive year. Management has acknowledged the weakness each year but has not implemented corrective action, citing budget constraints. The audit committee has not pressed management for remediation. The engagement partner should:', '["Downgrade the material weakness to a significant deficiency since the auditor has communicated it in prior years", "Cease communicating the weakness because repeated communication serves no further purpose under AU-C 265", "Communicate the material weakness again in writing and consider the implications for the overall audit strategy and risk assessment", "Issue an adverse opinion solely because the material weakness has persisted for three consecutive years"]'::jsonb, 2, 'Under AU-C 265.A15, a previously communicated material weakness that has not been remediated must be communicated again in writing each year. The auditor cannot downgrade or omit it merely because it was previously reported. The persistence also warrants reconsidering the audit approach under AU-C 315. Choice A is incorrect because the severity classification depends on the deficiency''s potential magnitude and likelihood, not on how many times it has been communicated—an unremediated material weakness remains a material weakness.', 'hard', 4),

-- Q11: medium / L3 — Analyzing qualitative factors in misstatement evaluation
(1, 'Misstatements and Control Deficiencies', 'Lakewood Pharmaceuticals has $22,000 in aggregate uncorrected misstatements, well below the $100,000 overall materiality level. However, $18,000 of this amount relates to an understatement of a regulatory compliance accrual that, if corrected, would cause the company to violate a debt covenant requiring a minimum current ratio of 1.5:1. The auditor should conclude that:', '["The misstatements are qualitatively material because they could trigger a debt covenant violation, despite being quantitatively immaterial", "The misstatements are immaterial because they are significantly below the overall materiality threshold", "The misstatements must be reclassified from uncorrected to corrected before the opinion is issued", "The debt covenant implications are a going concern issue unrelated to misstatement evaluation"]'::jsonb, 0, 'Under AU-C 450.11, the auditor evaluates uncorrected misstatements both quantitatively and qualitatively. Qualitative factors include whether a misstatement affects compliance with debt covenants, regulatory requirements, or contractual obligations. Even though $22,000 is well below the $100,000 materiality, the covenant violation makes it qualitatively material. Choice B is incorrect because AU-C 450.A16 specifically requires qualitative consideration beyond the numerical materiality threshold, and covenant violations are a key qualitative factor.', 'medium', 3),

-- Q12: medium / L3 — Analyzing effect of corrected misstatements on audit conclusions
(1, 'Misstatements and Control Deficiencies', 'During the audit of Brentwood Capital Partners, the audit team identified $95,000 in misstatements across investment valuations. Management corrected all identified amounts. The auditor should analyze whether these corrected misstatements:', '["Must be included in the aggregate of uncorrected misstatements to determine the opinion type", "May indicate risks of additional undetected misstatements, potentially requiring expanded audit procedures", "Eliminate the need for further testing in the investment valuation area since all errors were resolved", "Should be reported to those charged with governance only if they individually exceeded performance materiality"]'::jsonb, 1, 'Under AU-C 450.08, even when management corrects identified misstatements, the auditor should consider the nature, cause, and magnitude of those corrections. A significant volume of corrected misstatements may indicate systemic issues and a higher risk of undetected errors, warranting additional testing. Choice C is incorrect because correction of misstatements does not automatically validate the remaining population—the pattern of errors may indicate control weaknesses or systemic problems requiring expanded procedures under AU-C 450.A8.', 'medium', 3),

-- Q13: hard / L4 — Evaluating representation letter adequacy
(1, 'Misstatements and Control Deficiencies', 'Fenwick & Sterling LLP has completed testing for the 2025 audit of Atlas Industrial Group. Five uncorrected misstatements totaling $47,000 are documented, with overall materiality set at $200,000. Management provides a representation letter stating the effects of the uncorrected misstatements are immaterial, but provides no rationale for this belief and refuses to discuss the individual items. The auditor should:', '["Accept the representation letter as sufficient because the $47,000 aggregate is well below the $200,000 materiality", "Modify the opinion to qualified because management will not discuss individual misstatements with the audit team", "Include the uncorrected misstatements in the auditor''s report as an emphasis-of-matter paragraph", "Evaluate whether management''s unwillingness to discuss the items constitutes a scope limitation and consider its effect on the report"]'::jsonb, 3, 'Under AU-C 450.12, management must provide a representation that the effects of uncorrected misstatements are immaterial. However, under AU-C 580.A8, the auditor must evaluate the reliability of management representations. A blanket assertion without rationale, combined with refusal to discuss individual items, may indicate a scope limitation under AU-C 705. Choice A is incorrect because the representation letter alone is insufficient—AU-C 450 requires the auditor to independently evaluate the reasonableness of management''s assertion about immateriality.', 'hard', 4),

-- Q14: hard / L4 — Evaluating combined deficiencies across IT and manual controls
(1, 'Misstatements and Control Deficiencies', 'Sullivan & Burke LLP is auditing Northern Pacific Energy Corporation. The audit team identifies three separate control deficiencies: (1) the ERP system allows journal entries without secondary approval, (2) the monthly account reconciliation process lacks documented evidence of supervisory review, and (3) the IT department has not restricted access to the general ledger module. Individually, each deficiency''s potential misstatement is estimated at $30,000 against materiality of $250,000. The auditor should evaluate these deficiencies:', '["Individually, concluding each is a deficiency but not significant because each is far below materiality", "Individually, concluding each is a significant deficiency because it involves a key financial reporting control", "In combination, because together they could allow material misstatements to occur and remain undetected", "By recommending management hire additional staff, as the deficiencies indicate insufficient accounting personnel"]'::jsonb, 2, 'Under AU-C 265.A12, the auditor must consider whether individually insignificant control deficiencies, when combined, represent a significant deficiency or material weakness. These three deficiencies—uncontrolled journal entries, unreviewed reconciliations, and unrestricted system access—create overlapping gaps where errors could enter the system and remain undetected. Choice A is incorrect because evaluating each deficiency in isolation ignores the compounding effect; AU-C 265.A12 specifically requires assessment of deficiency combinations.', 'hard', 4),

-- Q15: medium / L2 — Applying the clearly trivial threshold to a specific amount
(1, 'Misstatements and Control Deficiencies', 'Hartwell & Associates LLP is auditing Cedar Point Distributors, which has overall materiality of $500,000 and performance materiality of $375,000. The engagement team sets the clearly trivial threshold at $25,000. During accounts payable testing, the team identifies a $28,000 misstatement caused by a duplicate vendor payment. Under AU-C 450, the auditor should:', '["Report the $28,000 misstatement directly to those charged with governance as a material weakness indicator", "Accumulate the $28,000 misstatement on the summary of uncorrected misstatements for aggregate evaluation", "Ignore the misstatement because it is below performance materiality and does not affect the audit opinion", "Require management to correct the $28,000 misstatement before continuing with any other audit procedures"]'::jsonb, 1, 'Under AU-C 450.05, the auditor must accumulate all identified misstatements during the audit except those that are clearly trivial. Since $28,000 exceeds the $25,000 clearly trivial threshold, it must be added to the summary of uncorrected misstatements for aggregate evaluation at the conclusion of the audit. Choice C is incorrect because being below performance materiality does not exempt a misstatement from accumulation—AU-C 450 requires all misstatements above the clearly trivial threshold to be accumulated regardless of their relationship to performance materiality.', 'medium', 2),

-- Q16: medium / L2 — Determining systematic vs. isolated misstatement treatment
(1, 'Misstatements and Control Deficiencies', 'Greenfield & Associates LLP is testing revenue transactions for Cascade Technologies Inc. In a sample of 60 invoices from Q4 2025, the auditor finds that seven invoices were posted to the wrong general ledger account because of an incorrectly configured account mapping rule implemented on October 1, 2025. Under AU-C 450, the auditor should treat this finding by:', '["Extending testing to all invoices processed after October 1 because the error is systematic and affects the entire population", "Limiting the misstatement to the seven sampled invoices because sampling errors cannot be extrapolated beyond the sample", "Classifying the error as clearly trivial because it involves account misclassification rather than a dollar amount error", "Communicating the finding only to IT personnel since the error originated from a system configuration issue"]'::jsonb, 0, 'Under AU-C 450.A5, when a misstatement is determined to be systematic—arising from a consistent cause affecting all similar transactions—the auditor should consider the effect on all transactions processed under the same conditions, not just the sample. The configuration error affects every invoice since October 1. Choice B is incorrect because AU-C 450 distinguishes between isolated and systematic errors; systematic errors require evaluation of the full affected population, unlike random sampling errors that are projected statistically.', 'medium', 2),

-- Q17: medium / L2 — Management representation letter content for uncorrected misstatements
(1, 'Misstatements and Control Deficiencies', 'Prescott Industries'' management provides a representation letter to Morrison & Hughes LLP at the conclusion of the 2025 audit. Three uncorrected misstatements totaling $65,000 have been identified, with materiality of $300,000. Under AU-C 450, the representation letter should include:', '["Management''s assertion that no additional misstatements exist beyond those identified by the audit team", "A commitment by management to correct the misstatements within 30 days of the audit report date", "An acknowledgment that the auditor has identified the exact amount of total financial statement error", "Management''s belief that the effects of uncorrected misstatements are immaterial, individually and in the aggregate"]'::jsonb, 3, 'Under AU-C 450.14, the auditor requests management to provide a written representation that the effects of uncorrected misstatements are immaterial, both individually and in the aggregate, to the financial statements as a whole. A summary of such items is typically attached to the representation letter. Choice A is incorrect because management cannot guarantee that no other misstatements exist—the representation specifically addresses only the identified uncorrected misstatements and management''s assessment of their materiality.', 'medium', 2),

-- Q18: medium / L3 — Analyzing performance materiality proximity risk
(1, 'Misstatements and Control Deficiencies', 'During the audit of Westbrook Hospitality Group, Kendall & Pierce LLP set overall materiality at $120,000 and performance materiality at $84,000. After completing all planned procedures, aggregate uncorrected misstatements total $78,000. The auditor should analyze this result by considering that:', '["No further action is needed because uncorrected misstatements are below both materiality and performance materiality", "An adverse opinion is required because uncorrected misstatements are close to performance materiality", "There is more than a negligible risk that total misstatements exceed overall materiality, given the proximity to performance materiality", "Performance materiality should be increased to $90,000 to create additional buffer above the detected misstatements"]'::jsonb, 2, 'Under AU-C 450.11, when aggregate uncorrected misstatements approach performance materiality, the auditor recognizes an increased risk that undetected misstatements, combined with uncorrected ones, could exceed overall materiality. The $78,000 uncorrected total against $84,000 performance materiality signals elevated risk. Choice A is incorrect because performance materiality is set below overall materiality specifically to account for undetected misstatements—proximity to performance materiality triggers additional evaluation, not a conclusion that no risk exists.', 'medium', 3),

-- Q19: hard / L3 — Analyzing cumulative effect of prior-period uncorrected misstatements
(1, 'Misstatements and Control Deficiencies', 'Irongate Construction Corp. had $45,000 in uncorrected misstatements carried forward from the 2024 audit, primarily from understated warranty accruals. During the 2025 audit, Lambert & Cross LLP identifies $52,000 in new uncorrected misstatements, also affecting warranty accruals. Overall materiality for 2025 is $110,000. The auditor should analyze the cumulative effect by:', '["Considering only the $52,000 current-year misstatements because prior-year amounts were already evaluated and accepted", "Evaluating the combined $97,000 effect on the current-year financial statements and reconsidering the risk assessment for warranty accruals", "Netting the prior-year and current-year misstatements because they relate to the same account and offset over time", "Disclosing the prior-year misstatements in an emphasis-of-matter paragraph without including them in the aggregate evaluation"]'::jsonb, 1, 'Under AU-C 450.A7, the auditor must consider the effect of prior-period uncorrected misstatements on current-year financial statements. The $45,000 carried forward combined with $52,000 in new misstatements totals $97,000 against $110,000 materiality, creating significant risk. The recurring warranty accrual issues also warrant reconsidering the risk assessment under AU-C 315. Choice A is incorrect because AU-C 450 explicitly requires evaluation of prior-period carryforward effects—ignoring them would understate the aggregate impact on current financial statements.', 'hard', 3),

-- Q20: easy / L1 — Definition of "pervasive" in misstatement context
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 705, when is a misstatement considered "pervasive" to the financial statements?', '["When the misstatement exceeds 10% of total assets or total revenue", "When management refuses to correct any identified misstatements during the audit", "When the misstatement relates to a single material account balance or disclosure", "When the misstatement is not confined to specific elements and affects the financial statements as a whole"]'::jsonb, 3, 'Under AU-C 705.06, misstatements are pervasive when they are not confined to specific elements, accounts, or items of the financial statements, or if confined, represent a substantial proportion of the financial statements, or relate to disclosures fundamental to users'' understanding. Choice C is incorrect because a misstatement confined to a single account balance is the opposite of pervasive—it is limited in scope and would typically support a qualified rather than an adverse opinion.', 'easy', 1),

-- Q21: medium / L3 — Analyzing design deficiency in automated control
(1, 'Misstatements and Control Deficiencies', 'Oakmont Financial Group relies on an automated three-way match control to verify purchase orders, receiving reports, and vendor invoices before authorizing payment. During the audit, Whitfield & Keller LLP discovers that the control only matches on dollar amounts but does not verify quantities or item descriptions. Several payments were made for incorrect items at the correct prices. This deficiency is best analyzed as:', '["A design deficiency, because the control was not designed to detect quantity and item description discrepancies", "An operating deficiency, because the three-way match is not functioning as management intended it to operate", "An inherent limitation of internal control that does not require formal classification or communication", "A significant deficiency only if the incorrect item payments individually exceeded performance materiality"]'::jsonb, 0, 'Under AU-C 265.A1, a design deficiency exists when a control is missing or not suitably designed to meet the control objective. The three-way match was designed only to compare dollar amounts, failing to address quantity and item verification—a gap in the control''s design. Choice B is incorrect because the control is operating exactly as designed by successfully matching dollar amounts, but the design itself is insufficient to achieve the full objective of verifying proper receipt of goods.', 'medium', 3),

-- Q22: medium / L2 — Individual vs. aggregate misstatement evaluation
(1, 'Misstatements and Control Deficiencies', 'Brookfield & Associates LLP is auditing Maplewood Retail Corp. with overall materiality of $200,000. The audit team identifies four uncorrected misstatements: a $35,000 overstated inventory, $28,000 understated accrued liabilities, $42,000 overstated accounts receivable, and $19,000 understated depreciation expense. Under AU-C 450, the auditor should evaluate these misstatements by:', '["Concluding they are immaterial because no single misstatement exceeds overall materiality", "Offsetting the overstatements against the understatements to arrive at a net income effect only", "Considering both the individual and aggregate effects, including the $124,000 gross aggregate, on the financial statements", "Requiring management to correct only the $42,000 accounts receivable misstatement as the largest individual item"]'::jsonb, 2, 'Under AU-C 450.11, the auditor evaluates uncorrected misstatements individually and in the aggregate. The gross aggregate of $124,000 must be considered, not merely the net effect. While individual items are below materiality, their combined impact approaches the $200,000 threshold and affects multiple financial statement elements. Choice B is incorrect because AU-C 450.A14 cautions against inappropriately netting misstatements across different accounts—each affects different financial statement elements and must be evaluated for its full impact.', 'medium', 2),

-- Q23: easy / L1 — Those charged with governance definition
(1, 'Misstatements and Control Deficiencies', 'Under auditing standards, who are "those charged with governance" for purposes of receiving control deficiency communications?', '["The chief financial officer and controller responsible for daily financial reporting oversight", "The person or organization with responsibility for overseeing the entity''s strategic direction and accountability", "External regulatory agencies that oversee the entity''s industry and filing requirements", "The entity''s external legal counsel who advises on internal control compliance matters"]'::jsonb, 1, 'Under AU-C 260.07, those charged with governance are the person(s) or organization(s) with responsibility for overseeing the strategic direction of the entity and obligations related to accountability, including oversight of financial reporting. This is commonly the board of directors or audit committee. Choice A is incorrect because the CFO and controller are members of management, not governance—AU-C 265 distinguishes between communications to management and communications to those charged with governance.', 'easy', 1),

-- Q24: hard / L4 — Evaluating withdrawal when governance ignores uncorrected material misstatements
(1, 'Misstatements and Control Deficiencies', 'Evergreen Partners LLP is concluding the audit of Bayshore Medical Devices. Aggregate uncorrected misstatements total $310,000 against materiality of $250,000. Management refuses to record corrections, and the board of directors supports management''s position despite the auditor''s detailed communication. The company is privately held with no regulatory filing requirements. The engagement partner should evaluate whether:', '["An unmodified opinion with an other-matter paragraph is sufficient to address the disagreement with management", "The auditor should reduce overall materiality to allow the misstatements to remain uncorrected without modification", "A qualified opinion is appropriate because the board has formally acknowledged the existence of the misstatements", "Withdrawal from the engagement may be necessary if the governance failure raises concerns about integrity under AU-C 210"]'::jsonb, 3, 'Under AU-C 450.A24, when management and governance refuse to correct material misstatements, the auditor considers whether to modify the opinion. In extreme cases where governance supports management''s position and the auditor questions the integrity of those charged with governance, AU-C 210 and AU-C 220 permit the auditor to consider withdrawal from the engagement. Choice C is incorrect because the board''s acknowledgment does not change the required opinion type—AU-C 705 bases modification on whether misstatements are material, regardless of management awareness.', 'hard', 4),

-- Q25: easy / L2 — Applying clearly trivial threshold (below threshold)
(1, 'Misstatements and Control Deficiencies', 'Birchwood Consulting Group has overall materiality of $80,000, performance materiality of $56,000, and a clearly trivial threshold of $4,000. The auditor identifies a $3,200 expense misclassification during testing. Under AU-C 450, the auditor should:', '["Accumulate the $3,200 misstatement because all identified misstatements must be formally tracked", "Not accumulate the $3,200 misstatement because it falls below the clearly trivial threshold", "Report the $3,200 misstatement to those charged with governance as a significant deficiency", "Require management to correct the $3,200 misstatement before completing fieldwork procedures"]'::jsonb, 1, 'Under AU-C 450.05, the auditor need not accumulate misstatements that are clearly trivial—amounts that are inconsequential both individually and in the aggregate. Since $3,200 is below the $4,000 clearly trivial threshold and is a simple classification error, it qualifies as clearly trivial. Choice A is incorrect because AU-C 450 specifically creates an exception for clearly trivial amounts to prevent the auditor from spending disproportionate effort tracking inconsequential items.', 'easy', 2),

-- Q26: medium / L3 — Analyzing IT control deficiency effect on substantive testing
(1, 'Misstatements and Control Deficiencies', 'During the audit of Magnolia Health Systems, Ellsworth & Park LLP identifies a deficiency in the automated access controls governing the patient billing system. Multiple unauthorized users had the ability to create and approve billing adjustments without supervisory oversight. The auditor should analyze this deficiency''s effect on the audit by:', '["Expanding substantive testing of billing adjustments because reduced control reliance increases detection risk that must be addressed", "Concluding that no additional testing is needed if the unauthorized users did not actually process any billing adjustments", "Limiting the communication to an oral notification to management since the deficiency is IT-related rather than financial", "Deferring evaluation to the next audit cycle since the access controls are scheduled for a system upgrade"]'::jsonb, 0, 'Under AU-C 265.A8 and AU-C 315.26, when the auditor identifies a control deficiency that prevents reliance on controls, the audit strategy must shift to greater substantive testing. Unauthorized billing access directly increases the risk of undetected misstatements in revenue, requiring expanded testing of adjustments processed. Choice B is incorrect because the existence of unauthorized access itself creates risk regardless of whether those users actually processed transactions—under AU-C 315, the possibility of undetected unauthorized processing cannot be ruled out.', 'medium', 3),

-- Q27: medium / L2 — Rollover vs. iron curtain approach to misstatement evaluation
(1, 'Misstatements and Control Deficiencies', 'Chapman & Rhodes LLP is evaluating uncorrected misstatements for Redwood Timber Corp. The 2024 audit had a $30,000 uncorrected overstatement of prepaid insurance that reversed naturally in 2025. In 2025, a new $25,000 overstatement of prepaid rent is identified. Under the rollover approach to evaluating these misstatements, the aggregate current-year income statement effect would be:', '["$55,000, because both misstatements must be summed regardless of whether the prior-year item reversed", "$30,000, because the prior-year misstatement takes precedence over current-year items in the evaluation", "$0, because the reversal of the prior-year misstatement completely offsets the current-year misstatement", "$25,000, because the rollover method considers only current-year originating misstatements after prior-year reversals"]'::jsonb, 3, 'Under AU-C 450.A7 and the rollover approach described in SEC SAB No. 99, the auditor evaluates the effect of misstatements originating in the current year on the current-year income statement. Since the 2024 prepaid insurance overstatement reversed in 2025, its income statement effect nets to zero under the rollover method. The current-year aggregate is the $25,000 new originating misstatement. Choice A is incorrect because the rollover approach specifically accounts for the natural reversal of prior-year balance sheet misstatements, avoiding double-counting.', 'medium', 2),

-- Q28: easy / L1 — AU-C 450 communication to management requirement
(1, 'Misstatements and Control Deficiencies', 'What does AU-C 450 require the auditor to communicate to management regarding identified misstatements?', '["All misstatements accumulated during the audit on a timely basis, requesting management to correct them", "Only misstatements that individually exceed performance materiality established for the engagement", "Only misstatements resulting from suspected fraud or illegal acts identified during testing", "Only misstatements that affect the income statement, excluding balance sheet classification errors"]'::jsonb, 0, 'Under AU-C 450.08, the auditor must communicate all misstatements accumulated during the audit to the appropriate level of management on a timely basis and request that management correct those misstatements. This includes all items above the clearly trivial threshold regardless of size. Choice B is incorrect because AU-C 450 requires communication of all accumulated misstatements, not just those exceeding performance materiality—even smaller misstatements are communicated so management can evaluate and correct them.', 'easy', 1),

-- Q29: easy / L1 — PCAOB likely misstatement definition
(1, 'Misstatements and Control Deficiencies', 'Under PCAOB standards, what is a "likely misstatement"?', '["A misstatement that management has confirmed will be corrected before the report is issued", "A misstatement identified through direct observation of the entity''s physical inventory count", "The auditor''s best estimate of total misstatement in a population based on projected sample results and known errors", "A misstatement that the auditor believes will reverse in the subsequent accounting period"]'::jsonb, 2, 'Under PCAOB AS 2810.17, a likely misstatement represents the auditor''s best estimate of the misstatement in a given account or disclosure, typically derived from projecting sample results to the entire population combined with known factual misstatements. Choice A is incorrect because management''s intent to correct is not relevant to the classification—likely misstatements are estimated through the auditor''s extrapolation methodology regardless of whether management plans to make adjustments.', 'easy', 1),

-- Q30: easy / L1 — Immaterial misstatement definition
(1, 'Misstatements and Control Deficiencies', 'Under auditing standards, when is an uncorrected misstatement considered immaterial?', '["When it is less than 5% of the entity''s net income for the period under audit", "When management provides written assurance that the misstatement will not recur in future periods", "When the misstatement was caused by an honest error rather than intentional manipulation by management", "When it would not reasonably be expected to influence the economic decisions of financial statement users"]'::jsonb, 3, 'Under AU-C 320.02, materiality is based on whether misstatements could reasonably be expected to influence the economic decisions of users. A misstatement that would not affect user decisions is immaterial, considering both quantitative thresholds and qualitative factors. Choice A is incorrect because no fixed percentage defines materiality—AU-C 320.04 states that materiality is a matter of professional judgment considering specific circumstances, not a mechanical application of any single benchmark.', 'easy', 1)
;

COMMIT;
